create table "public"."learning_ledger_entries" (
  "id" bigint generated by default as identity not null,
  "transaction_id" bigint not null,
  "line_number" smallint not null,
  "account_code" text not null,
  "amount_minor" bigint not null,
  "currency" text not null,
  "counterparty_type" text,
  "counterparty_reference" text,
  "created_at" timestamptz not null default now(),
  constraint "learning_ledger_entries_pkey" primary key (id),
  constraint "learning_ledger_entries_transaction_line_key" unique (transaction_id, line_number),
  constraint "learning_ledger_entries_transaction_id_fkey" foreign key (transaction_id) references public.learning_ledger_transactions(id) on delete restrict,
  constraint "learning_ledger_entries_line_number_check" check (line_number > 0),
  constraint "learning_ledger_entries_account_code_check" check (account_code ~ '^[a-z][a-z0-9_.]{2,80}$'::text),
  constraint "learning_ledger_entries_amount_check" check (amount_minor <> 0),
  constraint "learning_ledger_entries_currency_check" check (currency = 'NGN'::text),
  constraint "learning_ledger_entries_counterparty_type_check" check (counterparty_type is null or counterparty_type ~ '^[a-z][a-z0-9_]{1,40}$'::text)
);
alter table "public"."learning_ledger_entries" enable row level security;
create index learning_ledger_entries_account_idx on public.learning_ledger_entries using btree (account_code, created_at, id);
create trigger prevent_learning_ledger_entry_update_delete before update or delete on public.learning_ledger_entries for each row execute function public.prevent_learning_ledger_mutation();
create constraint trigger assert_learning_ledger_entry_balanced after insert on public.learning_ledger_entries deferrable initially deferred for each row execute function public.assert_learning_ledger_transaction_balanced();
grant delete, insert, select, update on table "public"."learning_ledger_entries" to "postgres", "service_role";
